import { Fragment, useCallback, useEffect, useMemo, useState, type ReactNode } from 'react';
import { Footer, Header } from './components/Frame.tsx';
import { notation } from './lib/notation.tsx';
import noticesRaw from './content/notices.json';

/**
 * One archival notice per folder, on the model of the BnF's « Archives et
 * manuscrits » notices, and the books the inventory spreads over several
 * folders.
 *
 * Everything shown is generated by scripts/notices.mjs from the inventory, the
 * transcriptions and the registries in src/content; nothing is written here
 * for a particular folder. The only transcription text is the author's own
 * tables of contents and plans, copied with his numbering and page numbers.
 */

interface TocEntry {
  level: number;
  label?: string;
  text: string;
  page?: string;
  heading?: boolean;
}
interface Toc {
  title: string;
  batch: number;
  pages?: string[];
  entries: TocEntry[];
  where: string;
}
interface Edition {
  id: string;
  title: string;
  editors: string | null;
  year: string | null;
  venue: string | null;
  url: string | null;
  kind: string;
  documents: { title: string; url: string }[];
}
interface Leaf {
  page: string;
  written: string;
  iso: string | null;
  kind: string;
  hand: string;
  context: string;
  batch: number;
}
interface Notice {
  cote: string;
  title: string;
  inventoryTitle: string;
  typology: string | null;
  date: string;
  leaves: Leaf[];
  proposed: { from: string | null; to: string | null; confidence: string; summary: string } | null;
  physical: {
    support: string[];
    pages: number;
    transcribed: number;
    batches: number;
    author: { max: number; notes: number } | null;
    diagrams: number;
    drawings: number;
    math: number | null;
  };
  languages: string[];
  resume: string[] | null;
  modern: boolean;
  tocs: Toc[];
  historique: string;
  group: { id: string; title: string; date: string; cotes: string[] } | null;
  editions: Edition[];
  subjects: string[];
  names: string[];
  findings: number;
  proofs: number;
}
interface BookEntry {
  cote: string;
  label?: string;
  text: string;
  range?: string | null;
  pages?: number;
  date?: string | null;
}
interface Book {
  id: string;
  title: string;
  date: string;
  cotes: string[];
  source: string;
  edition: string | null;
  editionUrl?: string;
  entries: BookEntry[];
  pages: number;
}
const DATA = noticesRaw as unknown as { built: string; books: Book[]; notices: Notice[] };

/**
 * The transcription's apparatus, as the generator encodes it: ⟦?…⟧ uncertain,
 * ⟦-…⟧ struck, ⟦…⟧ illegible. Plain runs go through the notation helper.
 */
function Marked({ text }: { text: string }): ReactNode {
  const out: ReactNode[] = [];
  let plain = '';
  let k = 0;
  const flush = () => {
    if (plain) out.push(<Fragment key={`p${k++}`}>{notation(plain)}</Fragment>);
    plain = '';
  };
  for (let i = 0; i < text.length; ) {
    if (text[i] !== '⟦') {
      plain += text[i++];
      continue;
    }
    let depth = 0;
    let j = i;
    for (; j < text.length; j++) {
      if (text[j] === '⟦') depth++;
      else if (text[j] === '⟧' && --depth === 0) break;
    }
    const body = text.slice(i + 1, j);
    flush();
    if (body.startsWith('?')) {
      out.push(
        <span key={`m${k++}`} className="underline decoration-dotted decoration-ink-400 underline-offset-2" title="lecture incertaine">
          <Marked text={body.slice(1)} />
        </span>,
      );
    } else if (body.startsWith('-')) {
      out.push(
        <s key={`m${k++}`} className="text-ink-400" title="biffé">
          <Marked text={body.slice(1)} />
        </s>,
      );
    } else {
      out.push(
        <span key={`m${k++}`} className="text-ink-400" title="illisible">
          […]
        </span>,
      );
    }
    i = j + 1;
  }
  flush();
  return <>{out}</>;
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="grid gap-1 border-t border-ink-100 py-2.5 sm:grid-cols-[11rem_1fr] sm:gap-4">
      <dt className="text-[12px] font-semibold uppercase tracking-wide text-ink-400">{label}</dt>
      <dd className="min-w-0 text-[13.5px] leading-relaxed text-ink-700">{children}</dd>
    </div>
  );
}

function TocList({ entries }: { entries: TocEntry[] }) {
  return (
    <ol className="mt-1.5 space-y-0.5 text-[13px]">
      {entries.map((e, i) => (
        <li
          key={i}
          className={`flex gap-2 ${e.heading ? 'mt-2 font-semibold text-ink-900' : 'text-ink-700'}`}
          style={{ paddingLeft: `${Math.max(0, e.level - 1) * 1.25}rem` }}
        >
          {e.label && <span className="tabular shrink-0 text-ink-500">{notation(e.label)}</span>}
          <span className="min-w-0 flex-1">
            <Marked text={e.text} />
          </span>
          {e.page && <span className="tabular shrink-0 pl-3 text-ink-500">{e.page}</span>}
        </li>
      ))}
    </ol>
  );
}

const KIND: Record<string, string> = {
  letter: 'lettre',
  leaf: 'feuillet',
  stamp: 'tampon',
  typescript: 'tapuscrit',
  other: 'autre',
  'dated page': 'page datée',
};
const HAND: Record<string, string> = {
  his: 'de sa main',
  typed: 'dactylographiée',
  machine: 'machine',
  other: 'autre main',
  unknown: 'main non identifiée',
};
const CONFIDENCE: Record<string, string> = { low: 'faible', medium: 'moyenne', high: 'bonne' };
const pageList = (p: string[]) => (p.length === 1 ? `p. ${p[0]}` : `p. ${p[0]}–${p[p.length - 1]}`);

function NoticeBody({ n }: { n: Notice }) {
  const ph = n.physical;
  const complete = ph.transcribed > 0 && ph.transcribed >= ph.pages - 2;
  return (
    <dl className="mt-3">
      <Field label="Cote">Université de Montpellier, fonds Grothendieck, {n.cote}.</Field>
      <Field label="Titre">
        <em>{n.title}</em> <span className="text-ink-400">[titre de l’inventaire]</span>
      </Field>
      <Field label="Date">
        <p>
          {n.date} <span className="text-ink-400">(datation de l’inventaire)</span>
        </p>
        {n.leaves.length > 0 && (
          <div className="mt-1.5">
            <p className="text-[12.5px] font-semibold text-ink-600">Dates sur les feuillets</p>
            <ul className="mt-0.5 text-[13px]">
              {n.leaves.map((l, i) => (
                <li key={i} title={l.context}>
                  <a href={`/#${n.cote}/${l.batch}`} className="tabular hover:text-brand-700">
                    p. {l.page}
                  </a>{' '}
                  — « {l.written} » ({KIND[l.kind] ?? l.kind}, {HAND[l.hand] ?? l.hand})
                </li>
              ))}
            </ul>
          </div>
        )}
        {n.proposed && (
          <div className="mt-1.5">
            <p className="text-[12.5px] font-semibold text-ink-600">Datation proposée</p>
            <p className="text-[13px]">
              {n.proposed.from ?? '?'}
              {n.proposed.to && n.proposed.to !== n.proposed.from ? `–${n.proposed.to}` : n.proposed.to ? '' : ' (terminus post quem)'}{' '}
              <span className="text-ink-400">(confiance {CONFIDENCE[n.proposed.confidence] ?? n.proposed.confidence})</span> :{' '}
              {notation(n.proposed.summary)}
            </p>
          </div>
        )}
      </Field>
      <Field label="Description physique">
        <ul className="space-y-0.5">
          <li>
            Support : {ph.support.length ? ph.support.join(', ') : 'non précisé'}
            {n.typology && <span className="text-ink-500"> — selon l’inventaire : {n.typology}</span>}.
          </li>
          <li>
            Importance matérielle : {ph.pages} pages selon l’inventaire ;{' '}
            {ph.transcribed ? `${ph.transcribed} pages transcrites (${ph.batches} lots)` : 'non transcrit'}.
          </li>
          {ph.author && (
            <li>Numérotation : pagination de l’auteur relevée par la transcription, jusqu’à sa p. {ph.author.max}.</li>
          )}
          {ph.transcribed > 0 && (
            <li>
              Écriture : {ph.diagrams} diagramme{ph.diagrams > 1 ? 's' : ''}, {ph.drawings} dessin{ph.drawings > 1 ? 's' : ''}
              {ph.math !== null && <> ; texte à {ph.math} % mathématique (formules)</>}.
            </li>
          )}
        </ul>
      </Field>
      <Field label="Langue">{n.languages.length ? n.languages.join(', ') : <span className="text-ink-400">non relevée (non transcrit)</span>}</Field>
      <Field label="Présentation du contenu">
        {n.resume ? (
          <>
            <p className="text-[12px] text-ink-400">D’après la lecture modernisée :</p>
            {n.resume.map((p, i) => (
              <p key={i} className="mt-1.5">
                {notation(p)}
              </p>
            ))}
          </>
        ) : (
          <p>
            {n.inventoryTitle} <span className="text-ink-400">(titre de l’inventaire ; dossier non encore lu)</span>
          </p>
        )}
      </Field>
      {n.tocs.length > 0 && (
        <Field label="Table des matières">
          {n.tocs.map((t, i) => (
            <div key={i} className={i ? 'mt-4' : ''}>
              <p className="text-[13px] font-semibold text-ink-900">
                {notation(t.title)}{' '}
                <span className="font-normal text-ink-400">
                  — table de l’auteur, {t.pages ? pageList(t.pages) : `lot ${t.batch}`} du fonds,{' '}
                  <a href={`/#${n.cote}/${t.batch}`} className="hover:text-brand-700">
                    transcription
                  </a>
                </span>
              </p>
              <TocList entries={t.entries} />
            </div>
          ))}
          <p className="mt-2 text-[11.5px] text-ink-400">
            Telle que la transcription la donne : numérotation et pages de l’auteur ; soulignement pointillé = lecture
            incertaine, barré = biffé, […] = illisible.
          </p>
        </Field>
      )}
      <Field label="Historique">{n.historique}</Field>
      <Field label="Sources complémentaires">
        <ul className="space-y-1">
          {n.editions.map((e) => (
            <li key={e.id}>
              {e.url ? (
                <a href={e.url} className="text-brand-700 hover:underline">
                  <em>{e.title}</em>
                </a>
              ) : (
                <em>{e.title}</em>
              )}
              {e.editors && `, éd. ${e.editors}`}
              {e.venue && `, ${e.venue}`}
              {e.year && ` (${e.year})`}.
              {e.documents.length > 0 && (
                <span className="text-ink-500"> Pour cette cote : {e.documents.map((d) => d.title).join(' ; ')}.</span>
              )}
            </li>
          ))}
          {n.group && (
            <li>
              Dans l’inventaire : ensemble « {n.group.title} »{n.group.date && ` ${n.group.date}`}
              {n.group.cotes.length > 0 && (
                <>
                  {' '}
                  — autres cotes :{' '}
                  {n.group.cotes.map((c, i) => (
                    <Fragment key={c}>
                      {i > 0 && ', '}
                      <a href={`#${c}`} className="tabular hover:text-brand-700">
                        {c}
                      </a>
                    </Fragment>
                  ))}
                </>
              )}
              .
            </li>
          )}
          {(n.findings > 0 || n.proofs > 0) && (
            <li>
              Sur l’onglet{' '}
              <a href="/findings/" className="text-brand-700 hover:underline">
                Findings
              </a>{' '}
              : {n.findings > 0 && `${n.findings} piste${n.findings > 1 ? 's' : ''} examinée${n.findings > 1 ? 's' : ''}`}
              {n.findings > 0 && n.proofs > 0 && ' ; '}
              {n.proofs > 0 && (
                <a href="/findings/#lean" className="hover:text-brand-700">
                  {n.proofs} preuve{n.proofs > 1 ? 's' : ''} Lean
                </a>
              )}
              .
            </li>
          )}
          {!n.editions.length && !n.group && !n.findings && !n.proofs && <li className="text-ink-400">—</li>}
        </ul>
      </Field>
      <Field label="Index">
        <p>
          <span className="text-ink-500">Sujets : </span>
          {n.subjects.length ? (
            <>
              {n.subjects.join(' ; ')} <span className="text-ink-400">(mots-clés de la lecture modernisée, en anglais)</span>
            </>
          ) : (
            <span className="text-ink-400">aucun relevé</span>
          )}
        </p>
        <p className="mt-1">
          <span className="text-ink-500">Noms cités : </span>
          {n.names.length ? n.names.join(' ; ') : <span className="text-ink-400">aucun relevé dans les registres</span>}
        </p>
      </Field>
      <Field label="Note">
        <p>
          {n.editions.length
            ? `Édition existante : ${n.editions.map((e) => `${e.title}${e.year ? ` (${e.year})` : ''}`).join(' ; ')}.`
            : 'Non édité.'}{' '}
          {ph.transcribed
            ? `Transcription de travail ${complete ? 'complète' : 'partielle'} (${ph.transcribed} pages sur ${ph.pages})${n.modern ? ' et lecture modernisée' : ''} disponibles dans le projet ; première passe, non vérifiée sur le fac-similé.`
            : 'Pas encore transcrit dans le projet.'}{' '}
          <a href={`/#${n.cote}`} className="text-brand-700 hover:underline">
            Voir le fac-similé
          </a>
          .
        </p>
      </Field>
    </dl>
  );
}

function BookCard({ b }: { b: Book }) {
  return (
    <li className="card p-5">
      <h3 className="titre text-[19px] leading-snug text-ink-900">{b.title}</h3>
      <p className="mt-1 text-[13px] text-ink-500">
        {b.date} · cotes {b.cotes[0]} à {b.cotes[b.cotes.length - 1]} · {b.pages} pages selon l’inventaire
      </p>
      <div className="mt-3 overflow-x-auto">
        <table className="w-full min-w-[560px] text-[13px]">
          <tbody>
            {b.entries.map((e, i) => (
              <tr key={i} className="border-t border-ink-100 align-top">
                <td className="tabular w-16 py-1.5 pr-2 text-ink-500">{e.label ?? ''}</td>
                <td className="py-1.5 pr-3 text-ink-800">
                  {notation(e.text)}
                  {e.range && <span className="text-ink-500"> — {e.range}</span>}
                </td>
                <td className="whitespace-nowrap py-1.5 pr-3 text-ink-500">{e.date ?? ''}</td>
                <td className="tabular whitespace-nowrap py-1.5 pr-3 text-right text-ink-500">{e.pages ? `${e.pages} p.` : ''}</td>
                <td className="whitespace-nowrap py-1.5 text-right">
                  {(i === 0 || b.entries[i - 1].cote !== e.cote) && (
                    <a href={`#${e.cote}`} className="tabular font-semibold text-ink-900 hover:text-brand-700">
                      {e.cote}
                    </a>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="mt-3 text-[12px] leading-relaxed text-ink-500">
        Table {b.source}.{' '}
        {b.edition}
        {b.editionUrl && (
          <>
            {' '}
            <a href={b.editionUrl} className="text-brand-700 hover:underline">
              Lien
            </a>
            .
          </>
        )}
      </p>
    </li>
  );
}

const norm = (s: string) =>
  s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();

/** Open the notice the URL points at, now and whenever the hash changes. */
function useHashOpen(setOpen: (f: (o: Set<string>) => Set<string>) => void, clearFilter: () => void) {
  useEffect(() => {
    const go = () => {
      const id = decodeURIComponent(location.hash.slice(1));
      if (!id) return;
      // A link to a notice must reach it even when the filter hides it.
      if (DATA.notices.some((n) => n.cote === id)) clearFilter();
      setOpen((o) => new Set(o).add(id));
      requestAnimationFrame(() => document.getElementById(id)?.scrollIntoView());
    };
    go();
    addEventListener('hashchange', go);
    return () => removeEventListener('hashchange', go);
  }, [setOpen, clearFilter]);
}

export function NoticesPage() {
  const [q, setQ] = useState('');
  const [open, setOpen] = useState<Set<string>>(() => new Set());
  const clearFilter = useCallback(() => setQ(''), []);
  useHashOpen(setOpen, clearFilter);
  const query = norm(q.trim());
  const notices = useMemo(
    () =>
      query
        ? DATA.notices.filter((n) => n.cote.startsWith(query) || norm(`${n.cote} ${n.inventoryTitle}`).includes(query))
        : DATA.notices,
    [query],
  );
  const books = query
    ? DATA.books.filter((b) => norm(b.title).includes(query) || b.cotes.some((c) => c.startsWith(query)))
    : DATA.books;
  const withToc = DATA.notices.filter((n) => n.tocs.length).length;
  const transcribed = DATA.notices.filter((n) => n.physical.transcribed).length;

  return (
    <>
      <Header path="/notices/" />

      <main className="mx-auto max-w-5xl px-5 py-12">
        <header className="max-w-[44em]">
          <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-ink-400">Notices</p>
          <h1 className="titre mt-2 text-[30px] leading-tight text-ink-900">Notices du fonds, dossier par dossier</h1>
          <p className="mt-4 text-[15.5px] leading-relaxed text-ink-600" lang="fr">
            Notices rédigées sur le modèle de la BnF (« Archives et manuscrits »), générées à partir de l’inventaire de
            Montpellier et des transcriptions du projet ; première passe. Une notice par cote ({DATA.notices.length}),
            dans l’ordre de l’inventaire : cote, titre, date, description physique, langue, présentation du contenu, table
            des matières de l’auteur quand une transcription en donne une, historique, sources, index et état de
            l’édition. {transcribed} dossiers sont transcrits ; {withToc} donnent une table ou un plan de sa main.
          </p>
        </header>

        <div className="mt-6 max-w-[44em] rounded-[var(--radius-card)] border border-encours-200 bg-encours-50 px-4 py-3 text-[13px] leading-relaxed text-ink-700">
          <strong className="font-semibold">Première passe, non vérifiée sur le fac-similé.</strong> Les dates de
          l’inventaire, celles écrites sur les feuillets et les datations proposées par le projet sont données séparément,
          jamais l’une pour l’autre. Les noms ne sont indexés que lorsqu’un registre du projet les relève.
        </div>

        <div className="mt-6">
          <label className="block max-w-md">
            <span className="sr-only">Filtrer par cote ou par titre</span>
            <input
              type="search"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Filtrer par cote ou par titre (147, topos, Picard…)"
              className="w-full rounded-lg border border-ink-200 bg-white px-3 py-2 text-[14px] text-ink-900 placeholder:text-ink-400 focus:border-brand-500 focus:outline-none"
            />
          </label>
          {query && (
            <p className="mt-1.5 text-[12.5px] text-ink-500">
              {notices.length} notice{notices.length > 1 ? 's' : ''}, {books.length} livre{books.length > 1 ? 's' : ''}.
            </p>
          )}
        </div>

        {books.length > 0 && (
          <section className="mt-10">
            <h2 id="livres" className="scroll-mt-16 text-[11px] font-bold uppercase tracking-[0.12em] text-ink-400">
              Livres répartis sur plusieurs cotes
            </h2>
            <ul className="mt-3 space-y-4">
              {books.map((b) => (
                <BookCard key={b.id} b={b} />
              ))}
            </ul>
          </section>
        )}

        <section className="mt-12">
          <h2 id="notices" className="scroll-mt-16 text-[11px] font-bold uppercase tracking-[0.12em] text-ink-400">
            Notices par cote
          </h2>
          <ul className="mt-3 space-y-2">
            {notices.map((n) => (
              <li key={n.cote} id={n.cote} className="card scroll-mt-16">
                <details
                  open={open.has(n.cote)}
                  onToggle={(e) => {
                    const isOpen = (e.currentTarget as HTMLDetailsElement).open;
                    setOpen((o) => {
                      if (isOpen === o.has(n.cote)) return o;
                      const s = new Set(o);
                      if (isOpen) s.add(n.cote);
                      else s.delete(n.cote);
                      return s;
                    });
                  }}
                >
                  <summary className="flex cursor-pointer list-none items-baseline gap-3 px-4 py-3">
                    <span className="tabular w-14 shrink-0 font-semibold text-ink-900">{n.cote}</span>
                    <span className="min-w-0 flex-1 text-[14px] text-ink-800">{n.title}</span>
                    <span className="hidden shrink-0 text-[12px] text-ink-400 sm:inline">
                      {n.date} · {n.physical.pages} p.
                      {n.tocs.length > 0 && ' · table'}
                    </span>
                  </summary>
                  {open.has(n.cote) && (
                    <div className="border-t border-ink-100 px-4 pb-4" lang="fr">
                      <NoticeBody n={n} />
                    </div>
                  )}
                </details>
              </li>
            ))}
          </ul>
        </section>

        <p className="mt-12 max-w-[44em] text-[12px] leading-relaxed text-ink-400">
          src/content/notices.json, généré le {DATA.built} par scripts/notices.mjs à partir de l’inventaire
          (catalogue.ts), de hand.json, dated-leaves.json, proposed-datings.json, editions.json, people-evidence.json,
          letters.json, findings.ts, proofs.ts et des transcriptions (tables des matières, mots-clés et résumés des
          lectures modernisées).
        </p>
      </main>

      <Footer />
    </>
  );
}
